#pragma once

#include <cassert>
#include <cstdint>
#include <cstddef>
#include <iostream>
#include <utility>

#include "common_internal/representation/finger_array.h"

namespace fh_index {
namespace internal {

// GetAPSize will get the size of the arithmetic progression
// As each FGD has a finger for the start, and multiple fingers generated by AP
// Therefore GetSize = GetAPSize + 1

class FingerGroupDescriptorValue {
 public:
  FingerGroupDescriptorValue(uint64_t ap_start_key = 0, size_t size = 0,
                             uint16_t step = 0,
                             FingerArray* finger_array = nullptr)
      : ap_start_key_(ap_start_key),
        ap_size_step_((size << kBitStep) | step),
        finger_array_(finger_array) {
    assert(size < (1ull << kBitSize));
  }

  void SetAPSize(size_t size) {
    assert(size < (1ull << kBitSize) && size > 0);
    ap_size_step_ = (size << kBitStep) | (ap_size_step_ & kMaskStep);
  }
  void SetAPStep(uint16_t step) {
    ap_size_step_ = (ap_size_step_ & kMaskSize) | step;
  }
  size_t GetAPSize() const { return ap_size_step_ >> kBitStep; }
  uint16_t GetAPStep() const { return uint16_t(ap_size_step_ & kMaskStep); }

  uint64_t GetAPKey(size_t idx) const {
    assert((idx < GetAPSize()));
    return ap_start_key_ + (idx << GetAPStep());
  }

  template <typename FingerType>
  FingerType GetFinger(size_t idx) const {
    assert((finger_array_ != nullptr));
    return finger_array_->GetFinger<FingerType>(idx);
  }

  template <typename FingerType>
  FingerType* GetFingerArray() const {
    assert((finger_array_ != nullptr));
    return finger_array_->fingers<FingerType>();
  }

  FingerArray* GetFingerArrayPtr() const {
    return finger_array_;
  }

  void Print() const {
    std::cout << "AP start key: " << ap_start_key_ << std::endl;
    std::cout << "AP size: " << GetAPSize() << std::endl;
    std::cout << "AP step: " << GetAPStep() << std::endl;
  }

  static constexpr size_t kBitStep = 16;
  static constexpr size_t kBitSize = 48;
  static constexpr uint64_t kMaskStep = (1ull << kBitStep) - 1;
  static constexpr uint64_t kMaskSize = ~kMaskStep;

  uint64_t ap_start_key_;
  // ap_size_step_[0:15] = step(16)
  // ap_size_step_[16:63] = size(48)
  uint64_t ap_size_step_;
  FingerArray* finger_array_;
};

// Unified FingerGroupDescriptor for both RO and RW
// FingerType is a template parameter to support different finger types
template <typename KeyType, typename FingerType>
struct FingerGroupDescriptor {
 public:
  using FGDValueType = FingerGroupDescriptorValue;

  FingerGroupDescriptor(KeyType start_key = 0,
                        uint64_t ap_start_key = 0, size_t size = 0,
                        uint16_t step = 0,
                        FingerArray* finger_array = nullptr)
      : key_(start_key),
        fgd_value_(ap_start_key, size, step, finger_array) {}

  FingerGroupDescriptor(std::pair<KeyType, FGDValueType> p)
      : key_(p.first), fgd_value_(p.second) {}

  void SetAPSize(size_t size) { fgd_value_.SetAPSize(size); }
  void SetAPStep(uint16_t step) { fgd_value_.SetAPStep(step); }
  void SetFingerArray(FingerArray* finger_array) {
    fgd_value_.finger_array_ = finger_array;
  }

  size_t GetAPSize() const { return fgd_value_.GetAPSize(); }
  uint16_t GetAPStep() const { return fgd_value_.GetAPStep(); }
  size_t GetSize() const { return GetAPSize() + 1; }

  uint64_t GetAPKey(size_t idx) const {
    assert((idx < GetAPSize()));
    return fgd_value_.GetAPKey(idx);
  }

  const FingerType* GetFingerAddr(size_t idx) const {
    assert(idx < GetSize());
    return &(fgd_value_.GetFingerArray<FingerType>()[idx]);
  }

  FingerType GetFinger(size_t idx) const {
    return *GetFingerAddr(idx);
  }

  size_t Decode(uint64_t key) const {
    if (GetAPSize() == 0 || key < fgd_value_.ap_start_key_) {
      return 0;
    } else {
      size_t idx = (key - fgd_value_.ap_start_key_) >> GetAPStep();
      idx = std::min(idx, GetAPSize() - 1);
      return idx + 1;
    }
  }

  void Print() const {
    std::cout << std::endl << "FGD: " << std::endl;
    std::cout << "Start key: " << key_ << std::endl;
    fgd_value_.Print();
  }

  KeyType key_;
  FGDValueType fgd_value_;
};

}  // namespace internal
}  // namespace fh_index
